insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"6c4026d1-2fad-4ec7-8723-92ab49780749","tecnica_info":{"dicas":["Aprender a técnica e adaptar ao lado tratado antes de realizar em casa."],"execucao":["Usar a mão contralateral para assistir a subida lateral do braço a tratar, sem impulso.","Parar na amplitude individualmente prescrita e regressar devagar; não é obrigatório chegar acima da cabeça."],"erros_comuns":["Forçar o fim da amplitude ou usar impulso.","Inclinar ou rodar o tronco para ganhar altura."],"pontos_chave":["A orientação da mão é adaptada ao conforto e à prescrição; não garante proteção de todas as estruturas.","Faça apenas as séries, repetições e tempos definidos na sessão.","Não aumente a amplitude apenas porque repetiu o movimento.","Reduza ou pare perante dor aguda ou agravamento persistente e peça ajuste do plano."],"posicao_inicial":["De pé, com tronco confortável e estável. Segurar um bastão leve com as duas mãos, adaptando a pega ao lado a tratar conforme ensino."]},"tecnica_notas":"Dicas\n• Aprender a técnica e adaptar ao lado tratado antes de realizar em casa.\n\nExecução\n• Usar a mão contralateral para assistir a subida lateral do braço a tratar, sem impulso.\n• Parar na amplitude individualmente prescrita e regressar devagar; não é obrigatório chegar acima da cabeça.\n\nErros comuns\n• Forçar o fim da amplitude ou usar impulso.\n• Inclinar ou rodar o tronco para ganhar altura.\n\nPontos-chave\n• A orientação da mão é adaptada ao conforto e à prescrição; não garante proteção de todas as estruturas.\n• Faça apenas as séries, repetições e tempos definidos na sessão.\n• Não aumente a amplitude apenas porque repetiu o movimento.\n• Reduza ou pare perante dor aguda ou agravamento persistente e peça ajuste do plano.\n\nPosição inicial\n• De pé, com tronco confortável e estável. Segurar um bastão leve com as duas mãos, adaptando a pega ao lado a tratar conforme ensino."}'::jsonb - 'created_at') x where t.id='934c3aca-a45b-4553-b6fc-92f540e4b7aa';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"e7e1ba5d-2c00-4905-9e64-9ebbba95c985","tecnica_info":{"dicas":["Se tiver dificuldade, faça o exercício de costas encostadas a uma parede."],"execucao":["Usar a mão contralateral para ajudar a elevar o braço a tratar à frente, dentro da amplitude autorizada.","Regressar devagar com assistência. Não aumentar a amplitude automaticamente ao longo das repetições."],"erros_comuns":["Não incline o tronco para os lados nem arqueie as costas para trás.","Não encolha o ombro em direção à orelha.","Mantenha o cotovelo esticado, sempre que possível."],"pontos_chave":["Esta é uma mobilização assistida, não garantia de ausência de carga muscular.","Adaptar ao lado tratado e fazer apenas a dose da sessão.","Não é necessário chegar acima da cabeça; respeitar os limites cirúrgicos e o ensino individual.","Parar perante dor aguda ou agravamento persistente."],"posicao_inicial":["De pé, com os pés à largura dos ombros, joelhos ligeiramente fletidos e abdominal contraído.","Segure com as duas mãos um bastão leve e comprido (um cabo de vassoura, por exemplo). Use uma pegada mista: uma palma virada para cima e outra virada para baixo."]},"tecnica_notas":"Dicas\n• Se tiver dificuldade, faça o exercício de costas encostadas a uma parede.\n\nExecução\n• Usar a mão contralateral para ajudar a elevar o braço a tratar à frente, dentro da amplitude autorizada.\n• Regressar devagar com assistência. Não aumentar a amplitude automaticamente ao longo das repetições.\n\nErros comuns\n• Não incline o tronco para os lados nem arqueie as costas para trás.\n• Não encolha o ombro em direção à orelha.\n• Mantenha o cotovelo esticado, sempre que possível.\n\nPontos-chave\n• Esta é uma mobilização assistida, não garantia de ausência de carga muscular.\n• Adaptar ao lado tratado e fazer apenas a dose da sessão.\n• Não é necessário chegar acima da cabeça; respeitar os limites cirúrgicos e o ensino individual.\n• Parar perante dor aguda ou agravamento persistente.\n\nPosição inicial\n• De pé, com os pés à largura dos ombros, joelhos ligeiramente fletidos e abdominal contraído.\n• Segure com as duas mãos um bastão leve e comprido (um cabo de vassoura, por exemplo). Use uma pegada mista: uma palma virada para cima e outra virada para baixo."}'::jsonb - 'created_at') x where t.id='d3b9bea4-2f78-4da4-8301-6091b831ba19';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"7ff08c12-f5aa-48a1-bd6c-ab07db3d4de4","tecnica_info":{"dicas":["Aprender a variante com o profissional; fazer apenas a amplitude e a dose prescritas."],"execucao":["Com a mão contralateral, ajudar suavemente a deslocar a mão do lado tratado atrás do tronco até à amplitude ensinada.","É um movimento combinado do ombro; não procurar uma medida isolada de rotação interna nem puxar com força.","Manter apenas o tempo indicado na sessão, se prescrito, e regressar lentamente."],"erros_comuns":["Forçar a amplitude ou rodar o tronco para ganhar movimento.","Usar impulso ou contrariar restrições operatórias."],"pontos_chave":["Respeitar a amplitude e dose individuais; não aumentar automaticamente com as repetições.","Não aplicar um limiar fixo de dor ou de minutos como garantia de segurança.","Adaptar ao lado tratado; interromper perante dor aguda ou agravamento persistente."],"posicao_inicial":["Posição ensinada pelo profissional, com tronco estável e bastão leve, adaptada ao lado tratado. Mão do lado tratado atrás do tronco apenas se essa posição estiver autorizada."]},"tecnica_notas":"Dicas\n• Aprender a variante com o profissional; fazer apenas a amplitude e a dose prescritas.\n\nExecução\n• Com a mão contralateral, ajudar suavemente a deslocar a mão do lado tratado atrás do tronco até à amplitude ensinada.\n• É um movimento combinado do ombro; não procurar uma medida isolada de rotação interna nem puxar com força.\n• Manter apenas o tempo indicado na sessão, se prescrito, e regressar lentamente.\n\nErros comuns\n• Forçar a amplitude ou rodar o tronco para ganhar movimento.\n• Usar impulso ou contrariar restrições operatórias.\n\nPontos-chave\n• Respeitar a amplitude e dose individuais; não aumentar automaticamente com as repetições.\n• Não aplicar um limiar fixo de dor ou de minutos como garantia de segurança.\n• Adaptar ao lado tratado; interromper perante dor aguda ou agravamento persistente.\n\nPosição inicial\n• Posição ensinada pelo profissional, com tronco estável e bastão leve, adaptada ao lado tratado. Mão do lado tratado atrás do tronco apenas se essa posição estiver autorizada."}'::jsonb - 'created_at') x where t.id='b929675a-b7dc-45ba-a132-bf8f3ef1783b';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"37456953-6f3b-4071-bfdf-7f7e21360d95","tecnica_info":{"dicas":["Aprender a variante com o profissional; fazer apenas a amplitude e a dose prescritas."],"execucao":["Com a mão contralateral, ajudar a rodar suavemente o antebraço do lado tratado para fora, mantendo o cotovelo no lugar.","Manter apenas o tempo indicado na sessão, se prescrito, e regressar lentamente."],"erros_comuns":["Forçar a amplitude ou rodar o tronco para ganhar movimento.","Usar impulso ou contrariar restrições operatórias."],"pontos_chave":["Respeitar a amplitude e dose individuais; não aumentar automaticamente com as repetições.","Não aplicar um limiar fixo de dor ou de minutos como garantia de segurança.","Adaptar ao lado tratado; interromper perante dor aguda ou agravamento persistente."],"posicao_inicial":["Posição ensinada pelo profissional, com tronco estável e bastão leve, adaptada ao lado tratado. Braço junto ao corpo, cotovelo fletido e apoiado se indicado."]},"tecnica_notas":"Dicas\n• Aprender a variante com o profissional; fazer apenas a amplitude e a dose prescritas.\n\nExecução\n• Com a mão contralateral, ajudar a rodar suavemente o antebraço do lado tratado para fora, mantendo o cotovelo no lugar.\n• Manter apenas o tempo indicado na sessão, se prescrito, e regressar lentamente.\n\nErros comuns\n• Forçar a amplitude ou rodar o tronco para ganhar movimento.\n• Usar impulso ou contrariar restrições operatórias.\n\nPontos-chave\n• Respeitar a amplitude e dose individuais; não aumentar automaticamente com as repetições.\n• Não aplicar um limiar fixo de dor ou de minutos como garantia de segurança.\n• Adaptar ao lado tratado; interromper perante dor aguda ou agravamento persistente.\n\nPosição inicial\n• Posição ensinada pelo profissional, com tronco estável e bastão leve, adaptada ao lado tratado. Braço junto ao corpo, cotovelo fletido e apoiado se indicado."}'::jsonb - 'created_at') x where t.id='f00afd03-51ed-46d8-b2f3-d08028b98a03';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"e84c8789-82e1-463e-b414-f3feb09caa52","tecnica_info":{"dicas":["Executar depois de aprender a variante na clínica."],"execucao":["Usar a mão contralateral e o bastão para rodar suavemente o ombro, levando o antebraço na direção da bacia.","Manter o cotovelo e a frente do ombro apoiados.","Respeitar a amplitude e regressar."],"erros_comuns":["Forçar a amplitude ou usar movimentos bruscos.","Compensar com o tronco ou encolher o ombro."],"pontos_chave":["Aprender a direção do movimento e a posição com o profissional.","Não forçar a amplitude nem deslocar a frente do ombro para ganhar movimento.","A amplitude e a dose são individualizadas. Parar perante dor aguda ou agravamento persistente."],"posicao_inicial":["Deitado de costas, braço a cerca de 45 graus de afastamento, cotovelo a 90 graus e braço apoiado numa toalha; posição ensinada na clínica."]},"tecnica_notas":"Dicas\n• Executar depois de aprender a variante na clínica.\n\nExecução\n• Usar a mão contralateral e o bastão para rodar suavemente o ombro, levando o antebraço na direção da bacia.\n• Manter o cotovelo e a frente do ombro apoiados.\n• Respeitar a amplitude e regressar.\n\nErros comuns\n• Forçar a amplitude ou usar movimentos bruscos.\n• Compensar com o tronco ou encolher o ombro.\n\nPontos-chave\n• Aprender a direção do movimento e a posição com o profissional.\n• Não forçar a amplitude nem deslocar a frente do ombro para ganhar movimento.\n• A amplitude e a dose são individualizadas. Parar perante dor aguda ou agravamento persistente.\n\nPosição inicial\n• Deitado de costas, braço a cerca de 45 graus de afastamento, cotovelo a 90 graus e braço apoiado numa toalha; posição ensinada na clínica."}'::jsonb - 'created_at') x where t.id='52272d9d-48ca-412a-ad63-0dcaeec6e0e4';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"dcaee938-1b91-49a5-a1a7-cd98310af552","tecnica_info":{"dicas":["Ajustar o assento antes de selecionar a carga.","Expirar ao empurrar.","Reduzir a amplitude perante desconforto no ombro."],"execucao":["Empurrar as pegas para cima até à amplitude prescrita.","Evitar bloquear os cotovelos com impacto.","Baixar lentamente até uma posição confortável dos ombros."],"erros_comuns":["Arquear excessivamente a região lombar.","Compensar a carga com esforço excessivo do pescoço.","Descer além da amplitude tolerada.","Deixar as placas bater."],"pontos_chave":["Punhos alinhados com os antebraços.","Tronco apoiado.","Movimento simétrico.","Ombros controlados.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Ajustar o assento para colocar as pegas aproximadamente ao nível dos ombros.","Apoiar tronco, cabeça e bacia no encosto.","Segurar as pegas com punhos alinhados.","Manter os ombros confortáveis e o abdómen ativo."]},"tecnica_notas":"Dicas\n• Ajustar o assento antes de selecionar a carga.\n• Expirar ao empurrar.\n• Reduzir a amplitude perante desconforto no ombro.\n\nExecução\n• Empurrar as pegas para cima até à amplitude prescrita.\n• Evitar bloquear os cotovelos com impacto.\n• Baixar lentamente até uma posição confortável dos ombros.\n\nErros comuns\n• Arquear excessivamente a região lombar.\n• Compensar a carga com esforço excessivo do pescoço.\n• Descer além da amplitude tolerada.\n• Deixar as placas bater.\n\nPontos-chave\n• Punhos alinhados com os antebraços.\n• Tronco apoiado.\n• Movimento simétrico.\n• Ombros controlados.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Ajustar o assento para colocar as pegas aproximadamente ao nível dos ombros.\n• Apoiar tronco, cabeça e bacia no encosto.\n• Segurar as pegas com punhos alinhados.\n• Manter os ombros confortáveis e o abdómen ativo."}'::jsonb - 'created_at') x where t.id='922dc135-c81e-4c8e-89b6-39ef21a0a58b';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"e8d063b9-a260-494b-b91f-976125b5b84d","tecnica_info":{"dicas":["Usar carga leve.","Executar alternadamente se melhorar o controlo.","Expirar durante a elevação."],"execucao":["Elevar os braços à frente até à amplitude prescrita, geralmente sem ultrapassar a altura dos ombros.","Manter os cotovelos ligeiramente fletidos.","Baixar lentamente os halteres até à posição inicial."],"erros_comuns":["Ganhar balanço com o tronco.","Compensar a carga com esforço excessivo do pescoço.","Subir além da amplitude controlável.","Deixar cair os halteres."],"pontos_chave":["Tronco imóvel.","Pescoço relaxado.","Movimento controlado.","Punhos alinhados.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Em pé, com um halter em cada mão à frente das coxas.","Cotovelos ligeiramente fletidos.","Punhos neutros, ombros confortáveis e abdómen ativo."]},"tecnica_notas":"Dicas\n• Usar carga leve.\n• Executar alternadamente se melhorar o controlo.\n• Expirar durante a elevação.\n\nExecução\n• Elevar os braços à frente até à amplitude prescrita, geralmente sem ultrapassar a altura dos ombros.\n• Manter os cotovelos ligeiramente fletidos.\n• Baixar lentamente os halteres até à posição inicial.\n\nErros comuns\n• Ganhar balanço com o tronco.\n• Compensar a carga com esforço excessivo do pescoço.\n• Subir além da amplitude controlável.\n• Deixar cair os halteres.\n\nPontos-chave\n• Tronco imóvel.\n• Pescoço relaxado.\n• Movimento controlado.\n• Punhos alinhados.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Em pé, com um halter em cada mão à frente das coxas.\n• Cotovelos ligeiramente fletidos.\n• Punhos neutros, ombros confortáveis e abdómen ativo."}'::jsonb - 'created_at') x where t.id='c2349d5d-f3c2-4a61-b5fe-a03a45c2f0e5';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"d5943b95-ec8d-4c30-b950-58c0db5b6ca0","tecnica_info":{"dicas":["Imaginar que leva os cotovelos para trás.","Expirar ao puxar.","Reduzir a carga se não conseguir manter a coluna estável."],"execucao":["Puxar a pega em direção ao tronco.","Levar os cotovelos para trás sem elevar os ombros.","Fazer uma breve pausa com as omoplatas controladas.","Estender lentamente os braços sem arredondar o tronco."],"erros_comuns":["Balançar o tronco.","Contrair excessivamente o pescoço ou compensar com o tronco.","Projetar a cabeça para a frente.","Deixar a carga puxar o tronco."],"pontos_chave":["Tronco estável.","Cotovelos próximos do corpo.","Pescoço relaxado.","Regresso controlado.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Sentar-se com os pés apoiados e os joelhos ligeiramente fletidos.","Segurar a pega com os braços estendidos.","Manter o tronco alongado, o abdómen ativo e os ombros confortáveis."]},"tecnica_notas":"Dicas\n• Imaginar que leva os cotovelos para trás.\n• Expirar ao puxar.\n• Reduzir a carga se não conseguir manter a coluna estável.\n\nExecução\n• Puxar a pega em direção ao tronco.\n• Levar os cotovelos para trás sem elevar os ombros.\n• Fazer uma breve pausa com as omoplatas controladas.\n• Estender lentamente os braços sem arredondar o tronco.\n\nErros comuns\n• Balançar o tronco.\n• Contrair excessivamente o pescoço ou compensar com o tronco.\n• Projetar a cabeça para a frente.\n• Deixar a carga puxar o tronco.\n\nPontos-chave\n• Tronco estável.\n• Cotovelos próximos do corpo.\n• Pescoço relaxado.\n• Regresso controlado.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Sentar-se com os pés apoiados e os joelhos ligeiramente fletidos.\n• Segurar a pega com os braços estendidos.\n• Manter o tronco alongado, o abdómen ativo e os ombros confortáveis."}'::jsonb - 'created_at') x where t.id='2f31dee8-db8c-4336-beca-49620633d5f2';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"3fe4abac-ccab-4540-9514-4be7dda1b7b2","tecnica_info":{"dicas":["Ajustar os apoios antes de pegar no halter.","Expirar ao puxar.","Reduzir a carga se ocorrer rotação do tronco."],"execucao":["Puxar o halter em direção ao tronco, levando o cotovelo para trás.","Manter o tronco e a bacia imóveis.","Baixar lentamente até estender o braço."],"erros_comuns":["Rodar o tronco para elevar o halter.","Arredondar a região lombar.","Encolher o ombro.","Usar impulso."],"pontos_chave":["Coluna e bacia estáveis.","Cotovelo desloca-se para trás.","Evitar compensação excessiva do pescoço.","Movimento controlado.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Apoiar uma mão e o joelho do mesmo lado num banco estável.","Manter o outro pé no chão e segurar o halter com a mão livre.","Coluna alongada, bacia nivelada e ombro confortável."]},"tecnica_notas":"Dicas\n• Ajustar os apoios antes de pegar no halter.\n• Expirar ao puxar.\n• Reduzir a carga se ocorrer rotação do tronco.\n\nExecução\n• Puxar o halter em direção ao tronco, levando o cotovelo para trás.\n• Manter o tronco e a bacia imóveis.\n• Baixar lentamente até estender o braço.\n\nErros comuns\n• Rodar o tronco para elevar o halter.\n• Arredondar a região lombar.\n• Encolher o ombro.\n• Usar impulso.\n\nPontos-chave\n• Coluna e bacia estáveis.\n• Cotovelo desloca-se para trás.\n• Evitar compensação excessiva do pescoço.\n• Movimento controlado.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Apoiar uma mão e o joelho do mesmo lado num banco estável.\n• Manter o outro pé no chão e segurar o halter com a mão livre.\n• Coluna alongada, bacia nivelada e ombro confortável."}'::jsonb - 'created_at') x where t.id='81226e61-7224-4d23-b47f-58817269535d';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"6feb7567-eabe-4c13-bbf7-f82e38de7685","tecnica_info":{"dicas":["Reduzir a inclinação se não conseguir estabilizar o tronco.","Expirar ao puxar.","Usar carga que permita manter a posição até ao final."],"execucao":["Puxar os halteres em direção ao tronco.","Levar os cotovelos para trás sem rodar o tronco.","Baixar lentamente os halteres até à extensão dos braços."],"erros_comuns":["Arredondar a região lombar.","Levantar o tronco a cada repetição.","Contrair excessivamente o pescoço ou compensar com o tronco.","Usar balanço."],"pontos_chave":["Tronco permanece imóvel.","Coluna estável.","Cotovelos deslocam-se para trás.","Halteres sob controlo.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Em pé, com os pés à largura da bacia e um halter em cada mão.","Fletir ligeiramente os joelhos e inclinar o tronco a partir das ancas.","Manter a coluna alongada, braços pendentes e ombros confortáveis."]},"tecnica_notas":"Dicas\n• Reduzir a inclinação se não conseguir estabilizar o tronco.\n• Expirar ao puxar.\n• Usar carga que permita manter a posição até ao final.\n\nExecução\n• Puxar os halteres em direção ao tronco.\n• Levar os cotovelos para trás sem rodar o tronco.\n• Baixar lentamente os halteres até à extensão dos braços.\n\nErros comuns\n• Arredondar a região lombar.\n• Levantar o tronco a cada repetição.\n• Contrair excessivamente o pescoço ou compensar com o tronco.\n• Usar balanço.\n\nPontos-chave\n• Tronco permanece imóvel.\n• Coluna estável.\n• Cotovelos deslocam-se para trás.\n• Halteres sob controlo.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Em pé, com os pés à largura da bacia e um halter em cada mão.\n• Fletir ligeiramente os joelhos e inclinar o tronco a partir das ancas.\n• Manter a coluna alongada, braços pendentes e ombros confortáveis."}'::jsonb - 'created_at') x where t.id='9e074bb2-06c9-4c8c-b97c-27c374eaf477';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"099a88b4-af54-4d2a-9e8e-47ab47ba6038","tecnica_info":{"dicas":["Ajustar o assento antes da carga.","Expirar ao empurrar.","Reduzir a amplitude se houver desconforto anterior no ombro."],"execucao":["Empurrar as pegas para a frente, estendendo os cotovelos sem os bloquear com força.","Manter o tronco apoiado.","Regressar lentamente até uma amplitude confortável do ombro."],"erros_comuns":["Compensar a carga com esforço excessivo do pescoço.","Arquear excessivamente a região lombar.","Deixar os cotovelos recuar além da amplitude tolerada.","Deixar as placas bater."],"pontos_chave":["Punhos alinhados com os antebraços.","Ombros estáveis.","Movimento simétrico.","Regresso controlado.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Ajustar o assento para que as pegas fiquem aproximadamente ao nível médio do peito.","Apoiar cabeça, tronco e bacia no encosto.","Segurar as pegas com punhos neutros.","Manter os pescoço relaxado."]},"tecnica_notas":"Dicas\n• Ajustar o assento antes da carga.\n• Expirar ao empurrar.\n• Reduzir a amplitude se houver desconforto anterior no ombro.\n\nExecução\n• Empurrar as pegas para a frente, estendendo os cotovelos sem os bloquear com força.\n• Manter o tronco apoiado.\n• Regressar lentamente até uma amplitude confortável do ombro.\n\nErros comuns\n• Compensar a carga com esforço excessivo do pescoço.\n• Arquear excessivamente a região lombar.\n• Deixar os cotovelos recuar além da amplitude tolerada.\n• Deixar as placas bater.\n\nPontos-chave\n• Punhos alinhados com os antebraços.\n• Ombros estáveis.\n• Movimento simétrico.\n• Regresso controlado.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Ajustar o assento para que as pegas fiquem aproximadamente ao nível médio do peito.\n• Apoiar cabeça, tronco e bacia no encosto.\n• Segurar as pegas com punhos neutros.\n• Manter os pescoço relaxado."}'::jsonb - 'created_at') x where t.id='82beb619-8d25-4dc3-8505-22f8870483e6';
insert into public.wo_exercises(id,name,locais,categoria,is_active,photo_url,video_url,created_by,equipamento,is_favorite,tecnica_info,tecnica_notas,ajustes_maquina,tempo_exercicio_s,incremento_default,tempo_excentrico_s,contextos_exercicio,objetivos_exercicio,tempo_concentrico_s) select x.id,x.name,x.locais,x.categoria,x.is_active,x.photo_url,x.video_url,x.created_by,x.equipamento,x.is_favorite,x.tecnica_info,x.tecnica_notas,x.ajustes_maquina,x.tempo_exercicio_s,x.incremento_default,x.tempo_excentrico_s,x.contextos_exercicio,x.objetivos_exercicio,x.tempo_concentrico_s from public.wo_exercises t cross join lateral jsonb_populate_record(null::public.wo_exercises,to_jsonb(t) || '{"id":"bc3b1c37-7b01-4d05-991c-44111529ebcb","tecnica_info":{"dicas":["Usar ajuda para posicionar halteres pesados.","Expirar ao empurrar.","Não deixar cair os halteres no final da série."],"execucao":["Empurrar os halteres para cima até estender os cotovelos sem impacto.","Manter os halteres estáveis e simétricos.","Baixar lentamente até à amplitude confortável do ombro."],"erros_comuns":["Abrir excessivamente os cotovelos.","Arquear excessivamente a região lombar.","Deixar os punhos dobrarem para trás.","Descer além da amplitude tolerada."],"pontos_chave":["Pés firmes no chão.","Punhos sobre os cotovelos.","Ombros estáveis.","Movimento controlado e simétrico.","Parar se sentir dor aguda.","Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas."],"posicao_inicial":["Deitar-se num banco plano com a cabeça, o tronco e a bacia apoiados.","Pés firmes no chão.","Segurar um halter em cada mão, com punhos alinhados e cotovelos fletidos.","Estabilizar as omoplatas contra o banco."]},"tecnica_notas":"Dicas\n• Usar ajuda para posicionar halteres pesados.\n• Expirar ao empurrar.\n• Não deixar cair os halteres no final da série.\n\nExecução\n• Empurrar os halteres para cima até estender os cotovelos sem impacto.\n• Manter os halteres estáveis e simétricos.\n• Baixar lentamente até à amplitude confortável do ombro.\n\nErros comuns\n• Abrir excessivamente os cotovelos.\n• Arquear excessivamente a região lombar.\n• Deixar os punhos dobrarem para trás.\n• Descer além da amplitude tolerada.\n\nPontos-chave\n• Pés firmes no chão.\n• Punhos sobre os cotovelos.\n• Ombros estáveis.\n• Movimento controlado e simétrico.\n• Parar se sentir dor aguda.\n• Permitir o movimento natural das omoplatas; não as manter rigidamente deprimidas durante a elevação. Após cirurgia, realizar apenas na posição, carga e amplitude autorizadas.\n\nPosição inicial\n• Deitar-se num banco plano com a cabeça, o tronco e a bacia apoiados.\n• Pés firmes no chão.\n• Segurar um halter em cada mão, com punhos alinhados e cotovelos fletidos.\n• Estabilizar as omoplatas contra o banco."}'::jsonb - 'created_at') x where t.id='7715ca4f-2496-400e-879f-7515a2ba54a6';
