insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"83cb5197-b974-4143-a27b-daecbe336f5d","protocol_id":"26d55b98-bc20-41bf-8b66-77a13409b18b"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Elevação ativa do membro superior operado.\n• Contração resistida da coifa reparada.\n• Apoio/carga através do membro superior operado.\n• Puxar, empurrar ou levantar cargas com o membro operado.\n• Movimentos bruscos ou não controlados.\n• Progressão da mobilidade para além dos limites definidos para a reparação.","title":"Cuidados nesta fase"},{"text":"Cumprir utilização da ortótese conforme indicação cirúrgica.\nPosicionamento e proteção do membro superior nas atividades do dia a dia e durante o sono.\nEstratégias de controlo de dor/edema conforme indicação clínica.","title":"No dia a dia"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"5d9f0246-2950-4fbd-bab0-8219b2d5fa59:5e4fe38c-124a-4208-b139-cc96bb87561a","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='5e4fe38c-124a-4208-b139-cc96bb87561a';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"632634d9-5b6c-4e26-89e4-e9853771d4a8","protocol_id":"26d55b98-bc20-41bf-8b66-77a13409b18b"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Progressão agressiva ou forçada da amplitude.\n• Movimento através de dor significativa ou agravamento sustentado após exercício.\n• Elevação ativa com compensação escapular marcada.\n• Movimentos bruscos ou balísticos.\n• Carga pesada através do membro operado.\n• Puxar ou empurrar cargas significativas.\n• Fortalecimento resistido significativo da coifa nesta fase.\n• Qualquer movimento que contrarie restrições específicas da reparação ou do cirurgião.","title":"Cuidados nesta fase"},{"text":"Realizar apenas os exercícios e amplitudes prescritos, respeitando as restrições específicas da reparação.\nUtilizar progressivamente o membro superior nas atividades leves permitidas, evitando cargas, empurrar ou puxar para além do autorizado.\nMonitorizar a resposta ao exercício e evitar progressões que provoquem agravamento sustentado dos sintomas.","title":"No dia a dia"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"5d9f0246-2950-4fbd-bab0-8219b2d5fa59:a74ca9b3-c303-4779-8393-1ebb6ca54787","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='a74ca9b3-c303-4779-8393-1ebb6ca54787';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"e0c3f249-2f1b-4f50-a7aa-714075c395b8","protocol_id":"26d55b98-bc20-41bf-8b66-77a13409b18b"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Cargas elevadas ou aumentos rápidos da resistência.\n• Movimentos balísticos ou explosivos.\n• Treino até à falha muscular.\n• Compensação escapular marcada.\n• Progressão de carga com perda da qualidade do movimento.\n• Sobrecarga repetitiva acima da cabeça sem controlo adequado.\n• Exercício que provoque agravamento sustentado dos sintomas.\n• Progressões incompatíveis com restrições específicas da reparação ou indicação cirúrgica.","title":"Cuidados nesta fase"},{"text":"Progredir a resistência apenas conforme prescrito e de acordo com a resposta clínica.\nPrivilegiar qualidade do movimento e controlo escapular, evitando compensações.\nReduzir ou interromper a progressão da carga se ocorrer agravamento sustentado dos sintomas.","title":"No dia a dia"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"5d9f0246-2950-4fbd-bab0-8219b2d5fa59:5cff7b0b-c412-40d8-991b-58fec7a6f3ba","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='5cff7b0b-c412-40d8-991b-58fec7a6f3ba';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"b1c9ecdc-9c05-4259-9eaf-a62ffd50c63e","protocol_id":"26d55b98-bc20-41bf-8b66-77a13409b18b"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Progressões bruscas de carga.\n• Treino até à falha como objetivo do protocolo-base.\n• Carga elevada com perda da qualidade do movimento.\n• Compensação escapular marcada.\n• Movimentos explosivos/pliométricos ainda não preparados.\n• Repetição acima da cabeça excessiva sem tolerância prévia.\n• Exercícios que provoquem agravamento sustentado dos sintomas.\n• Progressão incompatível com restrições específicas da reparação ou cirurgião.","title":"Cuidados nesta fase"},{"text":"Progredir carga e complexidade apenas conforme prescrito.\nManter qualidade do movimento e controlo escapular durante todas as progressões.\nMonitorizar a resposta nas horas seguintes ao treino e ajustar a carga perante agravamento sustentado dos sintomas.\nNão iniciar trabalho desportivo ou profissional específico de elevada exigência sem progressão orientada.","title":"No dia a dia"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"5d9f0246-2950-4fbd-bab0-8219b2d5fa59:1df9eb72-255b-43a6-8f1b-e0529fd52ded","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='1df9eb72-255b-43a6-8f1b-e0529fd52ded';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"c1188ca8-2a03-4c5d-b356-2bfb96ca6b0c","protocol_id":"26d55b98-bc20-41bf-8b66-77a13409b18b"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Regresso à atividade, desporto ou trabalho-alvo sem autorização médica/cirúrgica quando aplicável.\n• Introdução de potência/pliometria/balísticos sem tolerância prévia demonstrada ou sem exigência da atividade-alvo.\n• Dor não aceitável ou agravamento sustentado dos sintomas durante ou após a tarefa.\n• Perda de controlo escapuloumeral ou compensações relevantes sob carga ou velocidade.\n• Progressão incompatível com restrições específicas da reparação ou indicação cirúrgica.","title":"Cuidados nesta fase"},{"text":"Progredir exposição específica à atividade/desporto/trabalho apenas conforme prescrito.\nMonitorizar a resposta sintomática nas horas seguintes ao treino ou à atividade.\nNão retomar competição, atividade de risco ou tarefa profissional de elevada exigência sem autorização explícita quando aplicável.","title":"No dia a dia"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"5d9f0246-2950-4fbd-bab0-8219b2d5fa59:68464c73-a843-44cf-a7f3-078cfd388992","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='68464c73-a843-44cf-a7f3-078cfd388992';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"31b91f0b-889e-4ede-aff5-a5bbfdc464b9","protocol_id":"f9449c56-39a6-4a56-829b-6ad698534ad0"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Fortalecimento ativo/resistido da coifa, apoio de peso no membro ou movimentos bruscos.\n• Abdução associada a rotação externa, extensão com rotação externa forçada, rotação interna forçada, mão atrás das costas e adução horizontal forçada.\n• Alongamentos forçados ou ultrapassar restrições operatórias.","title":"Cuidados nesta fase"},{"text":"Utilize a ortótese conforme indicação cirúrgica, habitualmente durante 4–6 semanas. Mova o cotovelo, punho e dedos com o braço apoiado, como lhe foi ensinado.","title":"Ortótese e apoio"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"634393bf-1543-41f5-9cc8-0552b38db33f:c7a15d55-b679-403e-acbb-91052ed0f3b4","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='c7a15d55-b679-403e-acbb-91052ed0f3b4';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"3c7ed429-4575-430b-9fe5-67517f8cb6c0","protocol_id":"f9449c56-39a6-4a56-829b-6ad698534ad0"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"• Forçar rotações terminais, adução horizontal ou cápsula posterior.\n• Introduzir rotação externa resistida precoce sem autorização específica.\n• Retirar ortótese ou progredir só pelo tempo pós-operatório.","title":"Cuidados nesta fase"},{"text":"Execute os exercícios assistidos lentamente, dentro dos limites operatórios. Não force as rotações nem retire a ortótese sem indicação.","title":"Movimentos assistidos"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"634393bf-1543-41f5-9cc8-0552b38db33f:802f0264-3167-4048-acd1-29f02dbaf1bd","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}]}'::jsonb) - 'created_at') x where t.id='802f0264-3167-4048-acd1-29f02dbaf1bd';
