insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"92c41ba4-2f63-471f-a626-75c855f1427a","protocol_id":"5dc65c84-724f-45f1-a053-fa43aeca1c9b"}'::jsonb || jsonb_build_object('data',t.data || '{"revisao_cientifica":"2026-10-28","recommendations_scope":"6f615517-75d9-5985-ac7b-e1ee7da14f03:ffdf91ab-b61f-57e1-8681-dbf658373394","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."}]}'::jsonb) - 'created_at') x where t.id='ffdf91ab-b61f-57e1-8681-dbf658373394';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"1d7d0a5a-bd0c-4d6a-8c31-8a52790195cd","protocol_id":"5dc65c84-724f-45f1-a053-fa43aeca1c9b"}'::jsonb || jsonb_build_object('data',t.data || '{"revisao_cientifica":"2026-10-28","recommendations_scope":"6f615517-75d9-5985-ac7b-e1ee7da14f03:cf30ea3f-aa3c-582d-aa2f-871b1d1b8aba","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."}]}'::jsonb) - 'created_at') x where t.id='cf30ea3f-aa3c-582d-aa2f-871b1d1b8aba';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"535b1b8c-f2d0-4de6-944b-df94be1ecd4f","protocol_id":"cd9bd984-8bc8-4be4-8997-954d0c65b795"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes_clinicas":[{"text":"[Certo] Este modelo destina-se a adultos com dedo em gatilho dos dedos II–V, sem infeção ou bloqueio fixo. O polegar e os casos pediátricos exigem adaptação própria. [Provável] Registar dedo/lado, grau de Quinnell ou Green, duração, bloqueio ativo/passivo, défice de extensão, impacto funcional, diabetes, doença reumática e tratamentos prévios.","title":"Âmbito e avaliação"},{"text":"[Certo] Ortótese e infiltração são opções com evidência. Um ensaio de 120 adultos não encontrou diferenças clinicamente importantes em dor e função entre ortótese, infiltração e combinação até um ano. Os critérios de inclusão limitam a extrapolação a múltiplos dedos e comorbilidades excluídas. [Provável] Decidir em função da gravidade, preferência e necessidade funcional, sem apresentar taxas universais de sucesso.","title":"Escolha do tratamento"},{"text":"[Certo] Foram estudados bloqueios da MCF e da IFP, com posições e horários diferentes. Ensaios e uma revisão recente apoiam o benefício a curto prazo. [Provável] Individualizar modelo, ajuste, tempo de utilização e mobilidade autorizada. Não fixar MCF a 10–15 graus para todos, nem afirmar que uso noturno é sempre superior ao diurno. Planear revisão, frequentemente por volta de seis semanas, mais cedo se piorar.","title":"Escolha da ortótese"},{"text":"[Certo] Um ensaio de 76 participantes, após infiltração, não demonstrou benefício adicional dos deslizamentos em dor, grau de ressalto ou recidiva às 24 semanas. Isto não prova ausência de utilidade para rigidez individual, mas impede prometer prevenção de recidivas. [Palpite] As doses deste modelo são propostas conservadoras, não um esquema validado.","title":"Limites do exercício"},{"text":"[Provável] Discutir infiltração ou referenciação perante sintomas persistentes, bloqueio recorrente ou incapacidade, sem impor seis semanas de exercícios prévios. Bloqueio fixo ou contratura exige avaliação precoce. A decisão após recidiva depende da resposta anterior e da avaliação; duas infiltrações não são um limiar obrigatório universal.","title":"Quando mudar a estratégia"},{"text":"[Provável] Distinguir Dupuytren, rigidez/bloqueio articular, patologia tendinosa pós-traumática e doença inflamatória. Associações sistémicas não justificam um painel laboratorial automático sem suspeita clínica. [Certo] Suspeita de infeção da bainha flexora exige avaliação urgente, sem esperar por febre ou por todos os sinais clássicos.","title":"Diagnóstico diferencial e segurança"},{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções complementares","text":"Não selecionar mobilidade de cotovelo, punho ou outros complementos apenas para atingir seis exercícios. Prescrever apenas quando há necessidade funcional; não alegar cura ou prevenção comprovada de recidiva."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"8c52630e-20d3-5996-96fc-fb09d344c53e:dbdf9aa6-273f-5074-b75d-121fa5f65796"}'::jsonb) - 'created_at') x where t.id='dbdf9aa6-273f-5074-b75d-121fa5f65796';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"d3e3357b-ae25-4e78-9619-3c4426075f63","protocol_id":"cd9bd984-8bc8-4be4-8997-954d0c65b795"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes_clinicas":[{"text":"[Certo] Este modelo destina-se a adultos com dedo em gatilho dos dedos II–V, sem infeção ou bloqueio fixo. O polegar e os casos pediátricos exigem adaptação própria. [Provável] Registar dedo/lado, grau de Quinnell ou Green, duração, bloqueio ativo/passivo, défice de extensão, impacto funcional, diabetes, doença reumática e tratamentos prévios.","title":"Âmbito e avaliação"},{"text":"[Certo] Ortótese e infiltração são opções com evidência. Um ensaio de 120 adultos não encontrou diferenças clinicamente importantes em dor e função entre ortótese, infiltração e combinação até um ano. Os critérios de inclusão limitam a extrapolação a múltiplos dedos e comorbilidades excluídas. [Provável] Decidir em função da gravidade, preferência e necessidade funcional, sem apresentar taxas universais de sucesso.","title":"Escolha do tratamento"},{"text":"[Certo] Foram estudados bloqueios da MCF e da IFP, com posições e horários diferentes. Ensaios e uma revisão recente apoiam o benefício a curto prazo. [Provável] Individualizar modelo, ajuste, tempo de utilização e mobilidade autorizada. Não fixar MCF a 10–15 graus para todos, nem afirmar que uso noturno é sempre superior ao diurno. Planear revisão, frequentemente por volta de seis semanas, mais cedo se piorar.","title":"Escolha da ortótese"},{"text":"[Certo] Um ensaio de 76 participantes, após infiltração, não demonstrou benefício adicional dos deslizamentos em dor, grau de ressalto ou recidiva às 24 semanas. Isto não prova ausência de utilidade para rigidez individual, mas impede prometer prevenção de recidivas. [Palpite] As doses deste modelo são propostas conservadoras, não um esquema validado.","title":"Limites do exercício"},{"text":"[Provável] Discutir infiltração ou referenciação perante sintomas persistentes, bloqueio recorrente ou incapacidade, sem impor seis semanas de exercícios prévios. Bloqueio fixo ou contratura exige avaliação precoce. A decisão após recidiva depende da resposta anterior e da avaliação; duas infiltrações não são um limiar obrigatório universal.","title":"Quando mudar a estratégia"},{"text":"[Provável] Distinguir Dupuytren, rigidez/bloqueio articular, patologia tendinosa pós-traumática e doença inflamatória. Associações sistémicas não justificam um painel laboratorial automático sem suspeita clínica. [Certo] Suspeita de infeção da bainha flexora exige avaliação urgente, sem esperar por febre ou por todos os sinais clássicos.","title":"Diagnóstico diferencial e segurança"},{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções complementares","text":"Não selecionar mobilidade de cotovelo, punho ou outros complementos apenas para atingir seis exercícios. Prescrever apenas quando há necessidade funcional; não alegar cura ou prevenção comprovada de recidiva."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"8c52630e-20d3-5996-96fc-fb09d344c53e:4b1f78a9-70da-5996-b857-c9f5a2150e4b"}'::jsonb) - 'created_at') x where t.id='4b1f78a9-70da-5996-b857-c9f5a2150e4b';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"93ff2378-16fd-4a65-8918-9a75acc3c8e2","protocol_id":"4bf32e13-1336-47df-aa42-d5392f797c59"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes_clinicas":[{"text":"[Certo] A evidência para exercícios específicos continua limitada. [Provável] Usar como complemento para mobilidade e função, sem prometer resolução mais rápida ou prevenção comprovada de recidiva.","title":"Lugar do exercício"},{"text":"[Certo] A síntese de 2023 favorece considerar infiltração de corticoide associada a ortótese tipo thumb-spica durante 3–4 semanas. O benefício adicional médio da imobilização foi estatisticamente significativo, mas inferior ao limiar clínico pré-definido. [Certo] A revisão de 2026 também favorece a combinação, com certeza baixa a muito baixa. [Provável] Individualizar indicação e duração; não apresentar uma opção como obrigatória para todos.","title":"Infiltração e ortótese"},{"text":"[Provável] Apoiar punho e base/MCP do polegar, deixando a articulação interfalângica livre quando adequado. Ajustar a posição confortável e evitar pressão sobre a estiloide radial ou compressão nervosa. [Provável] Definir por escrito o horário e a retirada para higiene e mobilidade; distinguir proteção nas tarefas de um regime de imobilização mais contínuo após infiltração.","title":"Prescrição da ortótese"},{"text":"[Certo] Um ensaio de viabilidade de 28 participantes estudou extensão isométrica dentro de tratamento multimodal, após duas semanas de ortótese, educação e mobilidade. Não demonstrou superioridade entre cargas. [Palpite] O esquema 3 × 10 s aqui proposto é uma adaptação conservadora, não reprodução de dose validada.","title":"Isométricos"},{"text":"[Provável] Registar duração, lateralidade, tarefas, gravidez/aleitamento, comorbilidades, infiltrações prévias e resposta. Rever função com tarefa escolhida e/ou QuickDASH. Ecografia pode ajudar se houver dúvida diagnóstica, resposta insuficiente ou necessidade de avaliar septação/orientar infiltração; não é obrigatória em todos. Persistência importante apesar de tratamento adequado pode justificar referenciação à cirurgia da mão.","title":"Avaliação e tratamento adicional"},{"text":"[Provável] Dor mais proximal com crepitação: considerar síndrome de intersecção, sem impor uma distância fixa. Parestesias dorsorradiais: considerar neuropatia do radial superficial. Dor trapézio-metacárpica: considerar rizartrose. [Certo] Dor pós-traumática na tabaqueira anatómica exige excluir fratura do escafoide; febre, ferida ou rubor progressivo exigem avaliação prioritária.","title":"Diagnóstico diferencial"},{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções complementares","text":"Não selecionar mobilidade de cotovelo, punho ou outros complementos apenas para atingir seis exercícios. Prescrever apenas quando há necessidade funcional; não alegar cura ou prevenção comprovada de recidiva."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"b2e56307-797a-547a-b93b-634b89fcc8b0:cc3f89b9-401e-547f-b250-1eb1cf2339cd"}'::jsonb) - 'created_at') x where t.id='cc3f89b9-401e-547f-b250-1eb1cf2339cd';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"1b708ac5-b04d-47bf-9dbc-b0ea5df8e9e4","protocol_id":"4bf32e13-1336-47df-aa42-d5392f797c59"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes_clinicas":[{"text":"[Certo] A evidência para exercícios específicos continua limitada. [Provável] Usar como complemento para mobilidade e função, sem prometer resolução mais rápida ou prevenção comprovada de recidiva.","title":"Lugar do exercício"},{"text":"[Certo] A síntese de 2023 favorece considerar infiltração de corticoide associada a ortótese tipo thumb-spica durante 3–4 semanas. O benefício adicional médio da imobilização foi estatisticamente significativo, mas inferior ao limiar clínico pré-definido. [Certo] A revisão de 2026 também favorece a combinação, com certeza baixa a muito baixa. [Provável] Individualizar indicação e duração; não apresentar uma opção como obrigatória para todos.","title":"Infiltração e ortótese"},{"text":"[Provável] Apoiar punho e base/MCP do polegar, deixando a articulação interfalângica livre quando adequado. Ajustar a posição confortável e evitar pressão sobre a estiloide radial ou compressão nervosa. [Provável] Definir por escrito o horário e a retirada para higiene e mobilidade; distinguir proteção nas tarefas de um regime de imobilização mais contínuo após infiltração.","title":"Prescrição da ortótese"},{"text":"[Certo] Um ensaio de viabilidade de 28 participantes estudou extensão isométrica dentro de tratamento multimodal, após duas semanas de ortótese, educação e mobilidade. Não demonstrou superioridade entre cargas. [Palpite] O esquema 3 × 10 s aqui proposto é uma adaptação conservadora, não reprodução de dose validada.","title":"Isométricos"},{"text":"[Provável] Registar duração, lateralidade, tarefas, gravidez/aleitamento, comorbilidades, infiltrações prévias e resposta. Rever função com tarefa escolhida e/ou QuickDASH. Ecografia pode ajudar se houver dúvida diagnóstica, resposta insuficiente ou necessidade de avaliar septação/orientar infiltração; não é obrigatória em todos. Persistência importante apesar de tratamento adequado pode justificar referenciação à cirurgia da mão.","title":"Avaliação e tratamento adicional"},{"text":"[Provável] Dor mais proximal com crepitação: considerar síndrome de intersecção, sem impor uma distância fixa. Parestesias dorsorradiais: considerar neuropatia do radial superficial. Dor trapézio-metacárpica: considerar rizartrose. [Certo] Dor pós-traumática na tabaqueira anatómica exige excluir fratura do escafoide; febre, ferida ou rubor progressivo exigem avaliação prioritária.","title":"Diagnóstico diferencial"},{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções complementares","text":"Não selecionar mobilidade de cotovelo, punho ou outros complementos apenas para atingir seis exercícios. Prescrever apenas quando há necessidade funcional; não alegar cura ou prevenção comprovada de recidiva."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"b2e56307-797a-547a-b93b-634b89fcc8b0:b6dc7b39-37ed-5f54-84c3-6f6bbcb1d95f"}'::jsonb) - 'created_at') x where t.id='b6dc7b39-37ed-5f54-84c3-6f6bbcb1d95f';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"52b7b515-fcd5-49c2-aacd-5df1a2770fcc","protocol_id":"ef0627ce-66b4-4056-8a03-5b61a2c5a5be"}'::jsonb || jsonb_build_object('data',t.data || '{"hep":["Realizar apenas os exercícios selecionados, com amplitude, carga e frequência individualmente definidas.","Manter a ortótese e as precauções no horário e período indicados pela equipa."],"objetivos":[{"id":"rsa_funcao","label":"Melhorar a função e a mobilidade necessárias às tarefas individuais, sem ultrapassar as restrições."},{"id":"rsa_protecao","label":"Executar o plano autorizado com controlo e resposta sintomática aceitável."}],"nota_ancora":"Modelo para seleção individual. As restrições dependem da indicação, técnica, estabilidade, tecidos reparados e orientação do cirurgião; não aplicar automaticamente a fratura ou revisão.","recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"Cumpra as indicações do cirurgião e as restrições da sua reparação. Não avance de fase apenas pelo número de semanas desde a operação.","title":"Proteção da cirurgia"},{"text":"Use a suspensão do braço conforme indicação cirúrgica. Execute os movimentos pendulares apenas como lhe foi ensinado.","title":"Ortótese"},{"title":"Quando contactar a equipa","text":"Contacte a equipa perante febre, ferida a drenar, dor que piora subitamente, perda nova de função, dormência ou fraqueza novas. Não aumente a carga nem continue um exercício para ultrapassar estes sintomas."},{"title":"Carga e movimentos","text":"Cumpra as posições, os apoios e as cargas autorizados pelo cirurgião. Não use um limite geral em quilogramas nem o tempo desde a cirurgia como autorização para progredir. Evite esforço repetitivo pesado e aumentos bruscos."}],"objetivos_serie":[{"id":"s3","op":"<=","tipo":"mensuravel","param":"eva.rep","texto":"Dor em repouso (EVA)","valor":2,"unidade":"/10"},{"id":"s5","tipo":"qualitativo","texto":"Uso estrito do sling","escala":"binario"},{"id":"s6","tipo":"qualitativo","texto":"Precaução anti-luxação respeitada (sem extensão+adução+RI)","escala":"binario"},{"id":"s7","tipo":"qualitativo","texto":"Activação isométrica do deltóide sem dor","escala":"binario"},{"id":"rom_individual","tipo":"qualitativo","texto":"Mobilidade passiva evolui dentro dos limites individuais autorizados, sem forçar para atingir um valor mínimo.","escala":"binario"}],"contraindicacoes":["Não realizar a combinação de extensão, adução e rotação interna nem posições extremas sem autorização nesta fase.","Não apoiar o peso do corpo, empurrar para se levantar ou levantar cargas com o membro sem autorização."],"revisao_cientifica":"2026-10-28","recommendations_scope":"bd1bc6d6-ffc6-468e-baf9-a1ba9e1157af:1b13244b-3faf-4917-bd18-b8bdbf1ff385","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Autorização cirúrgica","text":"Registar no plano individual as amplitudes, a carga, o apoio e a contração resistida autorizados. Considerar técnica, tecidos reparados, procedimentos associados e evolução clínica; as semanas não autorizam a progressão por si só."}],"limites_amplitude":[{"movimento":"Flexão passiva","tipo":"limite individual definido pelo cirurgião"},{"movimento":"Rotação externa passiva","tipo":"limite individual definido pelo cirurgião"}],"criterios_progressao":[{"id":"p1","texto":"Cicatrização e dor avaliadas, sem sinais de complicação."},{"id":"p2","texto":"Mobilidade compatível com os limites operatórios, sem exigência de um ângulo universal."},{"id":"p3","texto":"Autorização para progredir conforme avaliação e indicações cirúrgicas."}]}'::jsonb) - 'created_at') x where t.id='1b13244b-3faf-4917-bd18-b8bdbf1ff385';
