insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"619f802f-0c7b-48d2-a047-ab9b1c171275","protocol_id":"b5782544-ccf3-4dba-bc47-080b304e0b22"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"• Mobilização ou alongamento terminal forçados.\n• Tração brusca e exercícios que aumentem sustentadamente dor de repouso/noturna.\n• Aplicar este protocolo como substituto de restrições pós-operatórias.","title":"Cuidados nesta fase"},{"text":"Faça sessões breves de mobilidade, 1–3 vezes por dia conforme tolerância. Não procure o fim da amplitude através da dor.","title":"Mobilidade confortável"},{"text":"Reduza a exigência se aumentar de forma persistente a dor de repouso ou noturna. As variantes são alternativas; não as acumule.","title":"Resposta ao exercício"},{"title":"Se a evolução não for favorável","text":"Contacte o médico se a dor noturna ou a limitação piorarem ou se não conseguir realizar o plano. A equipa pode ajustar os exercícios e discutir outras opções de tratamento; não force para recuperar toda a amplitude de uma vez."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"d6728def-7427-44da-b353-fc2d082919ec:b94308d8-a1fc-4ded-a665-68ffbb0b21b4","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções de tratamento","text":"Considerar infiltração intra-articular quando clinicamente indicada, incluindo dor que dificulta a reabilitação; discutir benefícios, riscos e alternativas. Autoalongamento e reforço dependem da avaliação e têm evidência limitada para a dose ou variante exata. Não prometer recuperação completa espontânea em todos."}]}'::jsonb) - 'created_at') x where t.id='b94308d8-a1fc-4ded-a665-68ffbb0b21b4';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"28c5c1be-5c95-4bda-8468-3bf1d44c3074","protocol_id":"b5782544-ccf3-4dba-bc47-080b304e0b22"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"• Alongamento forçado e sessão com agravamento sustentado.\n• Acumular variantes equivalentes como se todas fossem obrigatórias.\n• Progredir apenas pelo calendário ou ignorar restrições cirúrgicas.","title":"Cuidados nesta fase"},{"text":"Realize a mobilidade prescrita 1–2 vezes por dia. Mantenha os alongamentos apenas durante o tempo indicado, sem forçar.","title":"Mobilidade regular"},{"text":"Não duplique movimentos equivalentes. Levar a mão atrás das costas só se lhe tiver sido indicado e ensinado.","title":"Variantes"},{"title":"Se a evolução não for favorável","text":"Contacte o médico se a dor noturna ou a limitação piorarem ou se não conseguir realizar o plano. A equipa pode ajustar os exercícios e discutir outras opções de tratamento; não force para recuperar toda a amplitude de uma vez."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"d6728def-7427-44da-b353-fc2d082919ec:6ac58284-4dc9-4927-beba-4fc97b1b230d","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções de tratamento","text":"Considerar infiltração intra-articular quando clinicamente indicada, incluindo dor que dificulta a reabilitação; discutir benefícios, riscos e alternativas. Autoalongamento e reforço dependem da avaliação e têm evidência limitada para a dose ou variante exata. Não prometer recuperação completa espontânea em todos."}]}'::jsonb) - 'created_at') x where t.id='6ac58284-4dc9-4927-beba-4fc97b1b230d';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"44c15817-7702-449b-b003-c3dca272e279","protocol_id":"b5782544-ccf3-4dba-bc47-080b304e0b22"}'::jsonb || jsonb_build_object('data',t.data || '{"recomendacoes":[{"text":"Faça apenas os exercícios selecionados para si, nas doses e amplitudes prescritas. As opções da biblioteca não são todas obrigatórias.","title":"O seu plano"},{"text":"• Sobrecarga brusca em amplitudes recém-adquiridas.\n• Dor aguda ou agravamento sustentado com a progressão.\n• Passagem autónoma a variantes de maior carga sem ensino e avaliação.","title":"Cuidados nesta fase"},{"text":"Mantenha a mobilidade diária se necessária e o reforço prescrito 2–3 dias por semana, com recuperação entre sessões.","title":"Recuperar função"},{"text":"Progrida primeiro a amplitude e depois a resistência. Altere uma variável de cada vez. Aprenda as variantes avançadas na clínica antes de as executar em casa.","title":"Progressão"},{"title":"Se a evolução não for favorável","text":"Contacte o médico se a dor noturna ou a limitação piorarem ou se não conseguir realizar o plano. A equipa pode ajustar os exercícios e discutir outras opções de tratamento; não force para recuperar toda a amplitude de uma vez."}],"revisao_cientifica":"2026-10-28","recommendations_scope":"d6728def-7427-44da-b353-fc2d082919ec:772bf3f1-7243-420a-8abf-40c5f683f388","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Opções de tratamento","text":"Considerar infiltração intra-articular quando clinicamente indicada, incluindo dor que dificulta a reabilitação; discutir benefícios, riscos e alternativas. Autoalongamento e reforço dependem da avaliação e têm evidência limitada para a dose ou variante exata. Não prometer recuperação completa espontânea em todos."}]}'::jsonb) - 'created_at') x where t.id='772bf3f1-7243-420a-8abf-40c5f683f388';
insert into public.protocol_phases(id,data,name,anchor_to,anchor_from,anchor_kind,phase_order,protocol_id) select x.id,x.data,x.name,x.anchor_to,x.anchor_from,x.anchor_kind,x.phase_order,x.protocol_id from public.protocol_phases t cross join lateral jsonb_populate_record(null::public.protocol_phases,to_jsonb(t) || '{"id":"ee646366-acb6-47b0-a0d3-0bf5660a67af","protocol_id":"88f744b9-d419-4ac6-95e1-29ea97a80884"}'::jsonb || jsonb_build_object('data',t.data || '{"hep":["Escolher os exercícios necessários e tolerados; as seis opções não são obrigatórias. Dose e frequência ajustadas individualmente.","Começar pelo limite inferior do intervalo de repetições. Nos exercícios de força, terminar com cerca de 2–3 repetições em reserva.","Cadência inicial: 2 segundos na fase de subida/encurtamento e 3 segundos no regresso. Repouso de 60 segundos entre séries, ajustável até 90 segundos.","A amplitude e resistência são individualizadas. Começar a elevação sem peso e aumentar gradualmente a carga conforme tolerância.","Reduzir carga, amplitude ou volume se piorarem claramente o sono ou a dor na manhã seguinte.","Se a irritabilidade impedir o exercício dinâmico, reavaliar a dose e considerar substituição individual por isométricos ensinados pelo profissional."],"revisao_cientifica":"2026-10-28","recommendations_scope":"e5fc39a1-8ce9-4f2b-b91e-46fc01b8be0e:cae3aab8-9a93-4036-ae04-e23c1fcccc69","recomendacoes_clinicas":[{"title":"Dose e escolha individual","text":"As opções não constituem um conjunto obrigatório. A dose da sessão é definida ou confirmada pelo prescritor; os parâmetros do catálogo não são uma dose ótima universal."},{"title":"Interpretação da evidência","text":"A norma apoia reabilitação ativa, não a superioridade deste conjunto, uma causa mecânica única da dor ou uma dose ótima. Não extrapolar a tendinopatia para uma reparação cirúrgica."}]}'::jsonb) - 'created_at') x where t.id='cae3aab8-9a93-4036-ae04-e23c1fcccc69';
